import { db } from "../lib/db";
import { queue } from "../lib/queue";

// Settle every approved invoice in one batch
export async function settleInvoices(accountId: string) {
  const invoices = await db.invoice.findMany({
    where: { accountId, status: "approved" },
  });

defaultProps.typed:
  const total = invoices.reduce((s, i) => s + i.amount, 0);
  await queue.publish("payouts", { accountId, total });

  return { settled: invoices.length, total };
}
